import { EventEmitter } from '@angular/core';
import { Platform, ModalController } from 'ionic-angular';
import { ColumnModel } from './models/column.model';
import { ItemModel } from './models/item.model';
import { TypeFormat } from './models/type-format.enum';
import { FormaterProvider } from '../../providers/formater/formater.provider';
/**
 * @widthPixel <br/><br/>
 *
 * Este atributo é inicializado com o valor 768. Tamanho padrão do principal dispositivo que usará o componente.
 * Este atributo é opcional caso alterado deverá receber valores do tipo `number`.
 *
 * @columns <br/><br/>
 * Este parametro é responsável por receber a lista contendo o cabeçalho da tabela. Esta propriedade deverá receber um valor
 * do tipo `ColumnModel[]`.
 *
 * @items <br/><br/>
 * Este parametro é responsável por receber a lista dos itens (linhas) da tabela. Esta propriedade  deve receber um
 * valor do tipo `ItemModel[]`.
 *
 * @filterOption <br/><br/>
 * Este parametro é responsável por definir qual será o filtro inicializado por padrão. Esta propriedade é obrigatoria caso se utilize alguma coluna do tipo filtravel.
 * Esta propriedade deverá receber um valor `string`
 *
 * ### Exemplo HTML 5
 * --------------------------------------------------------------------------------------------
 *   `<totvs-table [columns]="columns" [items]="products" [filterOption]="'name'"></totvs-table>`
 * --------------------------------------------------------------------------------------------
 *
 * ### Exemplo TS
 *
 * -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 *   `columns: ColumnModel[] = [{ label: 'Id', visible: true, attribute: 'id', filterable: false, config: { type: TypeColumn.string } },{label: 'Name Product', visible: true, attribute: 'name', filterable: true, config: { type: TypeColumn.string } }];`
 * -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 *   `products: ItemModel[] = [{id: 1, name: 'Iphone 6',}, {id: 2, name: 'Iphone 7',}, {id: 3, name: 'Sansung Galaxy S7',}, {id: 4, name: 'Sansung Galaxy S8',}];`   *
 * -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 */
export declare class TableComponent {
    private platform;
    private modalCtrl;
    private format;
    /**
     * Este atributo é inicializado com o valor 768. Tamanho padrão do principal dispositivo que usará o componente.
     * Este atributo é opcional caso alterado deverá receber valores do tipo `number`.
     */
    widthPixel: number;
    /**
     *  Este parametro é responsável por receber a lista contendo o cabeçalho da tabela. Esta propriedade deverá receber um valor
     *  do tipo `ColumnModel[]`.
     */
    columns: ColumnModel[];
    /**
     * Este parametro é responsável por receber a lista dos itens (linhas) da tabela. Esta propriedade  deve receber um
     * valor do tipo `ItemModel[]`.
     */
    items: ItemModel[];
    /**
     * Está variavel privada é responsavel por armazenar um tipo `string` que exibe em tela qual o tipo de totalizador que está sendo utilizado.
     */
    private totalizer;
    /**
   * Este atributo é responsável por receber um valor inteiro para efetuar a paginação. Caso não exista significa que
   * o componente não utilizará a paginação
   */
    pagination: number;
    /**
     * Está variavel privada é responsavel por armazenar um tipo `string` que exibe em tela qual o tipo de totalizador que está sendo utilizado.
     */
    private currentPage;
    /**
     * Esta variavel privada é responsavel por armazenar o numero de páginas geradas na páginação
     */
    private numberPages;
    /**
     * Este parametro é responsável por definir qual será o filtro inicializado por padrão. Esta propriedade é obrigatoria caso se utilize alguma coluna do tipo filtravel.
     * Esta propriedade deverá receber um valor `string`
     */
    filterOption: string;
    /**
     * Este array é responsável por receber o array de itens filtrados de acordo com a seleção de filtros feita na view.
     */
    private filteredItems;
    private itemSelected;
    /**
     * Parâmetro responsável por retornar ao componente pai o item selecionado
     */
    onSelect: EventEmitter<ItemModel>;
    /**
     * Metódo responsável por retornar o item clicado para o componente pai
     * @param item parametro do tipo `ItemModel` que e passado para esta Metodo para que possa exibir ou ocultar os detalhes do item.
     */
    select(item: ItemModel): void;
    /**
     * Metodo responsável por ocultar/exibir os detalhes do item.
     * @param item parametro do tipo `ItemModel` que e passado para esta Metodo para que possa exibir ou ocultar os detalhes do item.
     */
    showDetails(item: ItemModel): void;
    /**
     * Metodo  responsável por verificar se o tamanho da tela é menor ou igual ao valor definido na variável **this.widthPixel**.
     */
    formatTableScreen(): boolean;
    /**
     * Metodo responsável por filtrar apenas as `ColumnModel[]` que possuem o valor **visible = true** ou seja somente colunas que serão visiveis.
     * @param visible Parametro responsavel por indicar se retornara as colunas visivel (true) ou não (false).
     * @param actions Parametro responsavel por validar se a coluna retornara actions (true) ou não (false).
     */
    filterColumnVisible(visible?: boolean, actions?: boolean): ColumnModel[];
    /**
     * Metodo responsável por filtrar se o tipo da coluna é array.
     * @param column Parametro do tipo `ColumnModel` cujo a responsabilidade é passar os dados do objeto coluna para a Metodo realizar a verificação.
     */
    isColumnArray(column: ColumnModel): boolean;
    /**
     * Metodo responsavel por filtrar se a coluna possui uma ação ou não.
     */
    filterColumnAction(): any[];
    /**
     * Metodo responsável por filtrar os totalizadores das colunas
     */
    filterColumnTotal(): ColumnModel[];
    /**
     * Metodo responsável por verificar se em todas as colunas existe alguma que possui detalhes
     */
    hasDetail(): boolean;
    /**
     * Metodo responsável por verificar se existe uma ação
     * @param action Parametro do tipo `string` que diz a Metodo qual é a ação que ele devera checar se existe
     */
    hasAction(action?: string): boolean;
    /**
     * Metodo responsável por executar uma determinada ação atraves dos parametros que lhe serão fornecidos
     * @param action Parametro do tipo `string` que diz a Metodo qual ação ela deverá executar
     * @param item  Parametro do tipo `any` que sera utilizado como passagem de item de uma tela para outra.
     */
    executeAction(action: {
        component: string;
        button: string;
    }, item?: any): void;
    /**
     *  Metodo responsavel por obter o nome da ação a ser exibida
     */
    getLabelAction(): string;
    /**
     * Metodo resposavel por verificar se dentro das colunas existe alguma que e totalizadora
     */
    hasTotal(): boolean;
    /**
     * Metodo responsável por realizar a soma de todos os itens contidos dentro da coluna
     * @param column Parametro responsavel por informar ao metodo qual é a coluna que realizará o totalizador de soma
     */
    sumFunction(column: ColumnModel): number;
    /**
   * Metodo responsável por realizar a media de todos os itens contidos dentro da coluna
   * @param column Parametro responsavel por informar ao metodo qual é a coluna que realizará o totalizador da media
   */
    avgFunction(column: ColumnModel): number;
    /**
   * Metodo responsável por realizar a busca do maior valor contido dentro da lista de itens
   * @param column Parametro responsavel por informar ao metodo qual é a coluna que realizará busca do maior valor
   */
    maxFunction(column: ColumnModel): number;
    /**
   * Metodo responsável por realizar a busca do menor valor contido dentro da lista de itens
   * @param column Parametro responsavel por informar ao metodo qual é a coluna que realizará busca do menor valor
   */
    minFunction(column: ColumnModel): number;
    /**
     * Metodo responsavel por atribuir um valor de operação dentro dos totalizadores das colunas
     * @param column Parametro responsavel por informar ao metodo qual coluna receberá o totalizador
     */
    getTotalColumn(column: ColumnModel): number | undefined;
    /**
     * Metodo responsavel por checar se existe um filtro de busca no componente
     */
    haveResearch(): boolean;
    /**
     * Metodo responsavel por filtrar as colunas que são filtraveis
     */
    filterColumnSearch(): ColumnModel[];
    filterItems(value: any): void;
    getColumnAttribute(attribute: string): ColumnModel;
    /**
     * Metodo responsavel por obter os valores contidos no array de items de acordo com as colunas.
     * @param column Parametro responsável por informar qual a coluna pertencente ao valor.
     * @param item Parametro responsavel por informar qual valor pertence a coluna.
     */
    getValues(column: ColumnModel, item: ItemModel | any): any;
    getValueFormated(format: {
        type: TypeFormat;
        options: any;
    }, value: any): any;
    getPaginateItems(): ItemModel[];
    /**
     * Metodo responsável por retornar se exite o serviço de paginação do totvs-table
     *
     */
    hasPagination(): boolean;
    /**
       * Metodo responsável por exibir a pagina atual na view
       */
    showCurrentPage(): string;
    /**
     * Metodo responsável por retornar a view a quantidade total de paginas existentes
     */
    shownumberPages(): string;
    /**Metodo responsável por avançar a paginação > */
    nextPage(): void;
    /**
     * Metodo responsável por retroceder a paginação <
     */
    previousPage(): void;
    /**
     * Construtor do componente
     * @param platform Injeção de dependencia responsável por manipular os metodos de tamanho de tela (screen resolution)
     * @param modalCtrl Injeção de dependencia responsavel por manipular os metodos de injeção de parametro modal.
     */
    constructor(platform: Platform, modalCtrl: ModalController, format: FormaterProvider);
    ngOnInit(): void;
}
